def hex_volumes(pts, h):
    c = pts[h]                      # (n,8,3)
    ctr = c.mean(axis=1)
    quads = [(0,1,2,3),(4,7,6,5),(0,4,5,1),(1,5,6,2),(2,6,7,3),(3,7,4,0)]
    V = np.zeros(len(h))
    for q in quads:
        fc = c[:,q,:].mean(axis=1)
        for i in range(4):
            a,b = c[:,q[i],:]-ctr, c[:,q[(i+1)%4],:]-ctr
            V += np.einsum('ij,ij->i', np.cross(a,b), fc-ctr)/6.0
    return V

